import { test, expect } from '@playwright/test';

test.describe('Bulk Delete Selected Items', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/items');
  });

  test('should successfully bulk delete multiple selected items', async ({ page }) => {
    // Select multiple items using getByRole
    const itemCheckboxes = page.getByRole('checkbox');
    await itemCheckboxes.first().click();
    await itemCheckboxes.nth(1).click();
    await itemCheckboxes.nth(2).click();

    // Verify items are selected
    await expect(itemCheckboxes.first()).toBeChecked();
    await expect(itemCheckboxes.nth(2)).toBeChecked();

    // Click the bulk delete button using getByRole
    const deleteButton = page.getByRole('button', { name: /bulk delete/i });
    await deleteButton.click();

    // Verify confirmation modal appears
    const confirmModal = page.getByRole('dialog', { name: /confirm deletion/i });
    await expect(confirmModal).toBeVisible();

    // Click confirm button in modal
    const confirmButton = page.getByRole('button', { name: /confirm/i });
    await confirmButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/items deleted successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify deleted items are removed from the list
    const itemRows = page.getByRole('row', { name: /item/i });
    const remainingItems = await itemRows.filter({ has: page.getByText('Item 1') }).count();
    expect(remainingItems).toBe(0);
  });

  test('should handle empty selection and prevent bulk delete', async ({ page }) => {
    // Verify no items are selected initially
    const itemCheckboxes = page.getByRole('checkbox');
    await expect(itemCheckboxes.first()).not.toBeChecked();

    // Attempt to click bulk delete button without selecting any items
    const deleteButton = page.getByRole('button', { name: /bulk delete/i });
    await deleteButton.click();

    // Verify no confirmation modal appears
    const confirmModal = page.getByRole('dialog', { name: /confirm deletion/i });
    await expect(confirmModal).not.toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByText(/please select at least one item/i);
    await expect(errorMessage).toBeVisible();

    // Verify item list remains unchanged
    const itemRows = page.getByRole('row', { name: /item/i });
    const itemCount = await itemRows.count();
    expect(itemCount).toBeGreaterThan(0);
  });
});
